src = open("lectures.js", encoding="utf-8").read()
i = src.index("window.BUILTIN_LECTURES = ") + len("window.BUILTIN_LECTURES = ")
L = {l["id"]: l for l in json.loads(src[i:].rstrip().rstrip(";"))}
out = {}
for lec, prefix, opts in C:
    hits = [q for q, _ in L[lec]["cards"] if q.startswith(prefix)]
    if len(hits) != 1: sys.exit("Не найден ровно один вопрос: %s / %s (%d)" % (lec, prefix, len(hits)))
    if len(set(opts)) != len(opts): sys.exit("Повтор вариантов: " + prefix)
    out["b-" + lec + "|" + hits[0]] = opts
open("checks.js", "w", encoding="utf-8").write(
    "/* Сгенерировано tools/build_checks.py. Первый вариант верный, сайт перемешивает их сам. Карточек: %d */\nwindow.CHECKS = %s;\n" % (len(out), json.dumps(out, ensure_ascii=False, indent=1)))
print("checks:", len(out))
